    'ds_l8_start': 'sounds/voice/ds_l8_start.mp3',
    'ডিস্ট্রিবিউশন ট্রান্সফরমারে ফল্ট হয়েছে। বুশিং খোলার আগে তালা ও সতর্কবার্তা বোর্ড সঙ্গে নিন।': 'sounds/voice/ds_l8_start.mp3',
