    'ds_l9_start': 'sounds/voice/ds_l9_start.mp3',
    'মাঝরাতে রাস্তায় জরুরি ফল্ট ব্রেকডাউন। আলো নেই, দ্রুতগতিতে গাড়ি চলছে—টর্চ, ট্রাফিক কোন এবং রিফ্লেক্টিভ জ্যাকেট সঙ্গে নিন।': 'sounds/voice/ds_l9_start.mp3',
    'রাত দুপুরে লাইন ব্রেকডাউন হয়ে গেছে। রাস্তায় গাড়ি, আলো নেই। ফল্ট সারাতে হবে।': 'sounds/voice/ds_l9_start.mp3',
    'ds_l9_done': 'sounds/voice/ds_l9_done.mp3',
    'রাতের ইমার্জেন্সি কিট সম্পূর্ণ লোড হয়েছে। ট্রাফিক কোন দিয়ে কাজের জায়গা ঘিরে তবেই কাজ শুরু করবেন।': 'sounds/voice/ds_l9_done.mp3',
    'সাজ সম্পূর্ণ। ভোল্টেজ ডিটেক্টর, ডিসচার্জ রড, পোর্টেবল আর্থিং কিট, টর্চ, এফআরপি মই আর কোন-ফিতে ভ্যানে উঠেছে। এবার বের হওয়া যাবে।': 'sounds/voice/ds_l9_done.mp3',

    // =========================================================
    // লেভেল ১০ — ডাল লাইনের উপর
    // =========================================================
    'ds_l10_start': 'sounds/voice/ds_l10_start.mp3',
    'ঝড়ে গাছের ডাল লাইনের ওপর ভেঙে পড়েছে। লাইন ডি-এনার্জাইজ করে ডাল সরানোর জন্য শক্ত হাত-দড়ি সঙ্গে নিন।': 'sounds/voice/ds_l10_start.mp3',
    'ঝড়ে ডাল লাইনের উপর পড়েছে। লাইন ব্রেকডাউন। ডাল সরিয়ে লাইন চালু করতে হবে।': 'sounds/voice/ds_l10_start.mp3',
    'ds_l10_done': 'sounds/voice/ds_l10_done.mp3',
    'ভ্যান সম্পূর্ণ প্রস্তুত! লাইন বন্ধ ও আর্থিং নিশ্চিত করে তবেই ডাল সরানোর কাজে হাত দিন।': 'sounds/voice/ds_l10_done.mp3',
    'সাজ সম্পূর্ণ। ভোল্টেজ ডিটেক্টর, ডিসচার্জ রড, পোর্টেবল আর্থিং কিট আর হাত-দড়ি ভ্যানে উঠেছে। এবার বের হওয়া যাবে।': 'sounds/voice/ds_l10_done.mp3',
    'ds_l10_sickle': 'sounds/voice/ds_l10_sickle.mp3',
    'শাটডাউন ও আর্থিং নিশ্চিত না করে কাস্তে দিয়ে ডাল কাটবেন না! ভেজা ডাল বিদ্যুৎ পরিবাহী হয়ে জীবন কেড়ে নিতে পারে।': 'sounds/voice/ds_l10_sickle.mp3',
    'লাইন মৃত না করে কাস্তে দিয়ে ডাল কাটবেন না।': 'sounds/voice/ds_l10_sickle.mp3',

